   168	unsafe impl GlobalAlloc for K6Alloc {
   169	    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
   170	        let size = layout.size();
   171	        let Some(level) = reserve(size) else {
   172	            refuse(size);
   173	            return std::ptr::null_mut();
   174	        };
   175	        let ptr = System.alloc(layout);
   176	        if ptr.is_null() {
   177	            release(size);
   178	        } else {
   179	            note_peak(level);
   180	            CALLS.fetch_add(1, Ordering::SeqCst);
   181	        }
   182	        ptr
   183	    }
   184	
   185	    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
   186	        let size = layout.size();
   187	        let Some(level) = reserve(size) else {
   188	            refuse(size);
   189	            return std::ptr::null_mut();
   190	        };
   191	        let ptr = System.alloc_zeroed(layout);
   192	        if ptr.is_null() {
   193	            release(size);
   194	        } else {
   195	            note_peak(level);
   196	            CALLS.fetch_add(1, Ordering::SeqCst);
   197	        }
   198	        ptr
   199	    }
   200	
   201	    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
   202	        System.dealloc(ptr, layout);
   203	        release(layout.size());
   204	    }
   205	
   206	    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
   207	        let old = layout.size();
   208	        if new_size > old {
   209	            let Some(level) = reserve(new_size - old) else {
   210	                refuse(new_size - old);
   211	                return std::ptr::null_mut();
   212	            };
   213	            let moved = System.realloc(ptr, layout, new_size);
   214	            if moved.is_null() {
   215	                release(new_size - old);
   216	            } else {
   217	                note_peak(level);
   218	                // The move model: the old block is alive beside the new one.
   219	                note_move(level + old);
   220	                CALLS.fetch_add(1, Ordering::SeqCst);
   221	            }
   222	            moved
   223	        } else {
   224	            let moved = System.realloc(ptr, layout, new_size);
   225	            if !moved.is_null() {
   226	                release(old - new_size);
   227	                CALLS.fetch_add(1, Ordering::SeqCst);
   228	            }
   229	            moved
   230	        }
   231	    }
   232	}
